-- Auto-generate sections for roughly half of all seeded courses (every even courseID after the initial 10)
SELECT
  c.courseID,
  2, -- Spring 2025 term
  c.courseCode, -- use course prefix/number as CRN (e.g., FIN 4314)
  30,
  0,
  'TBD',
  'OPEN',
  CONCAT('Auto-seeded section for ', c.courseTitle)
FROM (
  SELECT
    courseID,
    courseName,
    CASE
      WHEN courseName REGEXP '^[A-Z]{2,}[[:space:]]+[0-9]{3,4}\\b'
        THEN TRIM(SUBSTRING_INDEX(courseName, ' ', 2))
      ELSE CONCAT('AUTO-', courseID, '-SP')
    END AS courseCode,
    CASE
      WHEN courseName REGEXP '^[A-Z]{2,}[[:space:]]+[0-9]{3,4}\\b'
        THEN TRIM(SUBSTRING(courseName, CHAR_LENGTH(TRIM(SUBSTRING_INDEX(courseName, ' ', 2))) + 1))
      ELSE courseName
    END AS courseTitle
  FROM courses
) c
WHERE c.courseID > 10   -- skip the manually defined courses above
  AND c.courseID % 2 = 0
ON DUPLICATE KEY UPDATE
  capacity = VALUES(capacity),
  status = VALUES(status);

-- Normalize course names to drop the code used for CRN (e.g., "FIN 4314 Intro" -> "Intro")
UPDATE courses
SET courseName = TRIM(SUBSTRING(courseName, CHAR_LENGTH(TRIM(SUBSTRING_INDEX(courseName, ' ', 2))) + 1))
WHERE courseName REGEXP '^[A-Z]{2,}[[:space:]]+[0-9]{3,4}[[:space:]]+';
